/**
 * Set the where clause for a belongs-to-many relation query.
 *
 * @param  \Illuminate\Database\Eloquent\Relations\BelongsToMany  $relation
 * @return \Illuminate\Database\Eloquent\Relations\BelongsToMany
 */
public function addWhereConstraints($relation)
{
    $parent = $relation->getParent();
    $keyName = $relation->getParentKeyName();

    $value = $keyName === $this->getKeyName()
        ? $this->getKey()
        : $this->getAttribute($keyName);

    if ($parent !== $this) {
        $value = $parent->getAttribute($keyName);
    }

    $foreignPivotKey = $relation->getForeignPivotKeyName();
    $table = $relation->getTable();
    $qualified = str_contains($foreignPivotKey, '.')
        ? $foreignPivotKey
        : $table.'.'.$foreignPivotKey;

    $relation->getQuery()->where($qualified, '=', $value);

    return $relation;
}

/**
 * Clone the model into a new, non-existing instance.
 *
 * @param  array|null  $except
 * @return static
 */
public function replicate(array $except = null)
{
    $defaults = array_values(array_filter([
        $this->getKeyName(),
        $this->getCreatedAtColumn(),
        $this->getUpdatedAtColumn(),
    ]));

    $attributes = Arr::except(
        $this->getAttributes(), $except ? array_unique(array_merge($except, $defaults)) : $defaults
    );

    return tap(new static, function ($instance) use ($attributes) {
        $instance->setRawAttributes($attributes);

        $instance->setRelations($this->relations);

        $instance->fireModelEvent('replicating', false);
    });
}

/**
 * Clone the model into a new, non-existing instance without raising any events.
 *
 * @param  array|null  $except
 * @return static
 */
public function replicateQuietly(array $except = null)
{
    return static::withoutEvents(fn () => $this->replicate($except));
}

/**
 * Determine if two models have the same ID and belong to the same table.
 *
 * @param  \Illuminate\Database\Eloquent\Model|null  $model
 * @return bool
 */
public function is($model)
{
    return ! is_null($model) &&
        $this->getKey() === $model->getKey() &&
        $this->getTable() === $model->getTable() &&
        $this->getConnectionName() === $model->getConnectionName();
}

/**
 * Determine if two models are not the same.
 *
 * @param  \Illuminate\Database\Eloquent\Model|null  $model
 * @return bool
 */
public function isNot($model)
{
    return ! $this->is($model);
}

/**
 * Get the database connection for the model.
 *
 * @return \Illuminate\Database\Connection
 */
public function getConnection()
{
    return static::resolveConnection($this->getConnectionName());
}

/**
 * Get the current connection name for the model.
 *
 * @return string|null
 */
public function getConnectionName()
{
    return $this->connection;
}

/**
 * Set the connection associated with the model.
 *
 * @param  string|null  $name
 * @return $this
 */
public function setConnection($name)
{
    $this->connection = $name;

    return $this;
}

/**
 * Resolve a connection instance.
 *
 * @param  string|null  $connection
 * @return \Illuminate\Database\Connection
 */
public static function resolveConnection($connection = null)
{
    return static::$resolver->connection($connection);
}

